insert into public.ppg_skill_domains
  (domain, label_th, label_en)
values
  ('Storyboard Design', 'การออกแบบสตอรีบอร์ด', 'Storyboard Design')
insert into public.ppg_modules
  (module_key, course_key, order_index, skill_domain, title_th, title_en, summary_th, summary_en, publication_state)
values
  ('chapter-02', 'presentation-program', 2, 'Storyboard Design', 'การออกแบบสตอรีบอร์ด', 'Storyboard design', 'ความหมาย หลักการ รูปแบบ และการสร้างสตอรีบอร์ด', 'What a storyboard is, its principles and forms, and how to build one.', 'published')
insert into public.ppg_lessons
  (lesson_key, module_key, order_index, title_th, title_en, what_learn_th, what_learn_en, why_th, why_en, body_th, body_en, what_next_th, what_next_en, publication_state)
values
  ('chapter-01-lesson-01', 'chapter-01', 1, 'การนำเสนอคืออะไร', 'What a presentation is', 'อธิบายความหมาย ความสำคัญ และจุดประสงค์ของการนำเสนอ', 'Explain what a presentation is, why it matters, and what it is for.', 'เมื่อรู้เป้าหมายก่อนออกแบบสไลด์ ทุกการตัดสินใจจะตรงทาง', 'When you know the goal before you design, every later choice has a direction.', 'การนำเสนอคือการสือสารความคิดหนึงเรื่องหใ้ผู้ฟังเข้าใจและนำไปใช้ ธุรกิจใช้การนำเสนอเพื่อหใ้ข้อมูล โน้มน้าว ฝึกอบรม หรือรายงานความก้าวหน้า', 'A presentation communicates one idea so an audience understands it and can act on it. In business, presentations inform, persuade, train, or report progress.', 'ตอไป: ประเภทของข้อมูลและโปรแกรมนำเสนอ', 'Next: types of information and presentation programs.', 'published'),
  ('chapter-01-lesson-02', 'chapter-01', 2, 'ประเภทของข้อมูลและโปรแกรมนำเสนอ', 'Types of information and presentation programs', 'เลือกข้อมูลและโปรแกรมนำเสนอหใ้เหมาะกับงาน', 'Choose information types and a presentation program that fit the job.', 'ข้อมูลแตละประเภทเล่าเรื่องต่างกัน และแตละโปรแกรมก็เหมาะกับสภาพการทำงานต่างกัน', 'Each kind of information tells a different story, and each program suits a different working situation.', 'ข้อมูลมีหลายประเภท เช่น ข้อความ ตัวเลข ตาราง แผนภูมิ ภาพ และไอคอน โปรแกรมนำเสนอที่ใช้บ่อยคือ PowerPoint ส่วน Google Slides, LibreOffice Impress, Keynote และ Canva ก็ทำงานคล้ายกัน', 'Information comes as text, numbers, tables, charts, images, and icons. PowerPoint is the common program; Google Slides, LibreOffice Impress, Keynote, and Canva are equivalents.', 'ตอไป: หลักการ การเตรียมตัว และตวัอยาง', 'Next: principles, preparation, and examples.', 'published'),
  ('chapter-01-lesson-03', 'chapter-01', 3, 'หลักการ การเตรียมตัว และตวัอยาง', 'Principles, preparation, and examples', 'ใช้หลักการออกแบบและการเตรียมตัวก่อนนำเสนอ', 'Apply design principles and prepare before you present.', 'ผู้ฟังจำสิ่งที่อ่านง่ายและเป็นระเบียบได้ดีกว่า และการซ้อมทำหใ้เราควบคุมเวลาได้', 'Audiences remember what is easy to read and well ordered, and rehearsal keeps you in control of time.', 'หลักการสำคัญคือหนึงสไลด์หนึงความคิด แบบอักษรอ่านง่าย ใช้สีและเลย์เอาต์เดียวกันทั้งชุด และมีโครงเปิด ประเด็นหลัก ปิด การเตรียมตัวคือรู้ผู้ฟัง เตรียมเนื้อหาหใ้เพียงพอ และซ้อมก่อนพูดจริง', 'Key principles: one idea per slide, readable type, one consistent colour and layout system, and an opening-main-closing structure. Preparation means knowing the audience, right-sizing the content, and rehearsing.', 'ตอไป: ภารกิจความรู้ และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published'),
  ('chapter-02-lesson-01', 'chapter-02', 1, 'สตอรีบอร์ดคืออะไร หลักการและองค์ประกอบ', 'Storyboard: meaning, principles, and components', 'อธิบายความหมาย หลักการ และองค์ประกอบของสตอรีบอร์ด', 'Explain what a storyboard is, its principles, and its components.', 'สตอรีบอร์ดช่วยเห็นลำดับเรืองราวก่อนลงมือสร้างสไลด์ จึงแก้โครงสร้างได้ถูกกว่า', 'A storyboard shows the sequence before you build slides, so structural fixes are cheaper.', 'สตอรีบอร์ดคือแผนลำดับของสไลด์ที่ร่างข้อความหลัก ภาพ และบันทึกผู้บรรยาย เก็บไว้ล่วงหน้า หลักการคือหนึงกรอบหนึงความคิด เรียงลำดับหใ้ต่อเนื่อง และคงรูปแบบเดียวกัน', 'A storyboard is a slide-by-slide plan that drafts the main message, visuals, and speaker notes in advance. Principles: one idea per frame, a continuous sequence, and one consistent form.', 'ตอไป: ประโยชน์ รูปแบบ และเทมเพลต', 'Next: benefits, forms, and templates.', 'published'),
  ('chapter-02-lesson-02', 'chapter-02', 2, 'ประโยชน์ รูปแบบ และเทมเพลต', 'Benefits, forms, and templates', 'เลือกวิธีทำสตอรีบอร์ดและเทมเพลตหใ้เหมาะกับงาน', 'Choose a storyboard form and template that fit the job.', 'การวางแผนก่อนสร้างช่วยประหยัดเวลาและลดการแก้ซ้ำ', 'Planning before building saves time and reduces rework.', 'สตอรีบอร์ดทำได้บนกระดาษ ในโครงเรื่อง หรือในกรอบดิจิทัล เทมเพลตช่วยหใ้รูปแบบสม่ำเสมอและใส่เนื้อหาได้เร็วขึ้น', 'A storyboard can be paper, an outline, or digital frames. Templates keep the form consistent and speed up content entry.', 'ตอไป: เตรียมข้อมูลและสร้างสตอรีบอร์ด', 'Next: preparing information and building the storyboard.', 'published'),
  ('chapter-02-lesson-03', 'chapter-02', 3, 'เตรียมข้อมูลและสร้างสตอรีบอร์ด', 'Preparing information and building the storyboard', 'รวบรวมเนื้อหาและสร้างสตอรีบอร์ดทีละกรอบ', 'Gather content and build a storyboard frame by frame.', 'เนื้อหาที่คัดแล้วทำหใ้แตละกรอบมีเป้าหมาย และลำดับเรืองราวไม่สะดุด', 'Curated content gives every frame a purpose and keeps the sequence smooth.', 'เริ่มจากเป้าหมายและผู้ฟัง รวบรวมข้อมูลจากแหล่งข้อมูลที่เชื่อถือได้ เลือกเฉพาะที่จำเป็น แล้วร่างกรอบตามลำดับ เปิด ประเด็นหลัก ปิด ตรวจสอบความต่อเนื่องและแก้ก่อนสร้างสไลด์', 'Start from the goal and audience, gather information from reliable sources, keep only what is needed, draft frames as opening-main-closing, then check the flow and revise before building.', 'ตอไป: ภารกิจความรู้ และข้อสอบหลังเรียน', 'Next: the Knowledge Mission and the chapter post-test.', 'published')
insert into public.ppg_lesson_steps
  (lesson_key, order_index, kind, body_th, body_en, check_prompt_th, check_prompt_en, check_answer_key, check_explanation_th, check_explanation_en)
values
  ('chapter-01-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะอธิบายความหมายและจุดประสงค์ของการนำเสนอได้', 'By the end you can explain what a presentation is and what it is for.', null, null, null, null, null),
  ('chapter-01-lesson-01', 2, 'explanation', 'เริ่มจากเป้าหมายเดียว เช่น หใ้ข้อมูล โน้มน้าว ฝึกอบรม หรือรายงานความก้าวหน้า แล้วจึงเลือกเนื้อหา', 'Start from one goal - inform, persuade, train, or report progress - then choose the content.', null, null, null, null, null),
  ('chapter-01-lesson-01', 3, 'example', 'ตวัอยางงานขาย: เสนอสินค้าหนึงชิ้นเพื่อหใ้ลูกค้าตัดสินใจซื้อ ไม่ใช่เล่าทุกอย่างเกี่ยวกับบริษัท', 'Sales example: propose one product so the customer can decide to buy, instead of telling everything about the company.', null, null, null, null, null),
  ('chapter-01-lesson-01', 4, 'check', '', '', 'จุดประสงค์หลักของการนำเสนอในงานธุรกิจคืออะไร', 'What is the main purpose of a business presentation?', 'c', 'การนำเสนอที่ดีมีเป้าหมายเดียวชัดเจน ข้อมูลและสือภาพช่วยสนับสนุนเป้าหมายนั้น ไม่ใช่แทนที่', 'A good presentation has one clear goal. Facts and visuals support that goal; they do not replace it.'),
  ('chapter-01-lesson-01', 5, 'summary', 'หนึงเป้าหมาย หนึงความคิดหลัก แล้วทุกอย่างจะตามมา', 'One goal, one main idea, and everything follows from it.', null, null, null, null, null),
  ('chapter-01-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะเลือกข้อมูลและโปรแกรมนำเสนอหใ้เหมาะกับงานได้', 'By the end you can choose information and a presentation program that fit the job.', null, null, null, null, null),
  ('chapter-01-lesson-02', 2, 'explanation', 'ข้อความเหมาะกับประเด็น ตัวเลขเหมาะกับการเปรียบเทียบ แผนภูมิเหมาะกับแนวโน้ม และภาพเหมาะกับการอธิบายสิ่งที่เห็น', 'Text suits a point, numbers suit a comparison, charts suit a trend, and images suit something visual.', null, null, null, null, null),
  ('chapter-01-lesson-02', 3, 'example', 'รายงานยอดขายรายเดือนควรใช้แผนภูมิแท่งคู่กับตัวเลขสรุป ไม่ควรใส่ตารางยาวทั้งหน้า', 'A monthly sales report uses a bar chart with a summary figure, not a full-page dense table.', null, null, null, null, null),
  ('chapter-01-lesson-02', 4, 'check', '', '', 'เมื่อต้องเปรียบเทียบยอดขายสามสาขา ควรใช้ข้อมูลประเภทใด', 'To compare sales across three branches, which information type works best?', 'b', 'แผนภูมิแท่งเปรียบเทียบค่าหลายกลุ่มได้ชัดเจนกว่าข้อความยาว', 'A bar chart compares values across groups more clearly than a long paragraph.'),
  ('chapter-01-lesson-02', 5, 'summary', 'เลือกข้อมูลหใ้ตรงกับคำถาม และเลือกโปรแกรมหใ้ตรงกับทีมและอุปกรณ์', 'Match the information to the question and the program to your team and devices.', null, null, null, null, null),
  ('chapter-01-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะใช้หลักการออกแบบและการเตรียมตัวนำเสนอได้', 'By the end you can apply design principles and prepare a talk.', null, null, null, null, null),
  ('chapter-01-lesson-03', 2, 'explanation', 'หนึงสไลด์หนึงความคิดช่วยหใ้ผู้ฟังเน้น ส่วนการซ้อมช่วยจับเวลาและแก้จุดที่ติดขัด', 'One idea per slide keeps focus; rehearsal fixes timing and rough spots.', null, null, null, null, null),
  ('chapter-01-lesson-03', 3, 'example', 'ตวัอยางฝึกอบรมพนักงานใหม่: เปิดด้วยปัญหา สามสไลด์หลัก และปิดด้วยขั้นตอนที่ต้องทำทันที', 'New-staff training example: open with the problem, three main slides, close with the steps to take now.', null, null, null, null, null),
  ('chapter-01-lesson-03', 4, 'check', '', '', 'ข้อใดคือหลักการออกแบบสไลด์ที่ดี', 'Which is a good slide design principle?', 'a', 'ความสม่ำเสมอและความอ่านง่ายช่วยหใ้ผู้ฟังติดตามได้ ไม่ใช่การเปลี่ยนสไตล์ตลอดเวลา', 'Consistency and readability help the audience follow; constant style changes do not.'),
  ('chapter-01-lesson-03', 5, 'summary', 'หลักการง่าย ๆ เตรียมหใ้พอดี ซ้อมหใ้จริง แล้วนำเสนออย่างมั่นใจ', 'Simple principles, right-sized preparation, real rehearsal, confident delivery.', null, null, null, null, null),
  ('chapter-02-lesson-01', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะอธิบายความหมายและองค์ประกอบของสตอรีบอร์ดได้', 'By the end you can explain a storyboard and its components.', null, null, null, null, null),
  ('chapter-02-lesson-01', 2, 'explanation', 'แตละกรอบควรมีข้อความหลักหนึงข้อความ ภาพหรือแผนภูมิที่ช่วยสือสาร และบันทึกสิ่งที่ผู้พูดจะอธิบาย', 'Each frame needs one main message, a visual or chart that helps, and a note on what the speaker will say.', null, null, null, null, null),
  ('chapter-02-lesson-01', 3, 'example', 'ตวัอยางข้อเสนอขาย: กรอบ 1 ปัญหาลูกค้า กรอบ 2 วิธีแก้ กรอบ 3 ราคาและขั้นตอนตอไป', 'Sales proposal example: frame 1 the customer problem, frame 2 the solution, frame 3 price and next steps.', null, null, null, null, null),
  ('chapter-02-lesson-01', 4, 'check', '', '', 'องค์ประกอบใดควรมีในสตอรีบอร์ดแตละกรอบ', 'Which component belongs in each storyboard frame?', 'a', 'กรอบสตอรีบอร์ดเก็บสาระสำคัญที่ต้องสือสาร ไม่ใช่รายละเอียดการตกแต่ง', 'A storyboard frame keeps the essential message, not decoration details.'),
  ('chapter-02-lesson-01', 5, 'summary', 'หนึงกรอบหนึงความคิด พร้อมภาพและบันทึกที่จำเป็น', 'One idea per frame, with the visual and note it needs.', null, null, null, null, null),
  ('chapter-02-lesson-02', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะเลือกวิธีและเทมเพลตสตอรีบอร์ดที่เหมาะกับงานได้', 'By the end you can choose a storyboard form and template that fit the job.', null, null, null, null, null),
  ('chapter-02-lesson-02', 2, 'explanation', 'งานเดี่ยวเร่งด่วนอาจใช้กระดาษหรือโครงเรื่อง ส่วนทีมงานที่ต้องแชร์ไฟล์ควรใช้กรอบดิจิทัลในโปรแกรมนำเสนอ', 'A quick solo task may use paper or an outline; a team task that shares files should use digital frames in the presentation program.', null, null, null, null, null),
  ('chapter-02-lesson-02', 3, 'example', 'ทีมขายใช้กรอบดิจิทัลใน PowerPoint และแชร์ลิงก์หใ้หัวหน้าตรวจก่อนสร้างสไลด์จริง', 'A sales team uses digital frames in PowerPoint and shares a link for the lead to review before building.', null, null, null, null, null),
  ('chapter-02-lesson-02', 4, 'check', '', '', 'เมื่อใดควรใช้สตอรีบอร์ดแบบดิจิทัล', 'When should you use a digital storyboard?', 'a', 'สตอรีบอร์ดดิจิทัลเหมาะกับทีมงานเพราะแชร์ แก้ไข และติดตามเวอร์ชันได้ง่าย', 'A digital storyboard suits team work because it is easy to share, edit, and track.'),
  ('chapter-02-lesson-02', 5, 'summary', 'เลือกวิธีหใ้ตรงกับทีม เลือกเทมเพลตหใ้ตรงกับเวลา', 'Match the form to the team and the template to the time you have.', null, null, null, null, null),
  ('chapter-02-lesson-03', 1, 'objective', 'เมื่อจบบทเรียนนี้ คุณจะเตรียมข้อมูลและสร้างสตอรีบอร์ดตามลำดับได้', 'By the end you can prepare information and build a storyboard in order.', null, null, null, null, null),
  ('chapter-02-lesson-03', 2, 'explanation', 'เขียนเป้าหมายเป็นหนึงประโยคเดียว วางกรอบเปิดและปิดก่อน แล้วเติมประเด็นหลักทีละกรอบ', 'Write the goal as one sentence, place the opening and closing frames first, then add main points one frame at a time.', null, null, null, null, null),
  ('chapter-02-lesson-03', 3, 'example', 'ตวัอยางรายงานความก้าวหน้า: กรอบ 1 ผลลัพธ์หลัก กรอบ 2 ปัญหา กรอบ 3 แผนตอไปพร้อมตัวเลขและแผนภูมิที่ตรงประเด็น', 'Progress report example: frame 1 the headline result, frame 2 the problem, frame 3 the next plan, with focused numbers and a chart.', null, null, null, null, null),
  ('chapter-02-lesson-03', 4, 'check', '', '', 'ขั้นตอนแรกของการสร้างสตอรีบอร์ดคืออะไร', 'What is the first step in building a storyboard?', 'b', 'เป้าหมายและผู้ฟังคือตัวกำหนดเนื้อหาและลำดับของทุกกรอบ', 'The goal and audience determine the content and order of every frame.'),
  ('chapter-02-lesson-03', 5, 'summary', 'เป้าหมายก่อนเนื้อหาหลัง กรอบสุดท้ายคือเรืองราวที่ต่อเนื่อง', 'Goal first, content next, and a sequence that holds together.', null, null, null, null, null)
insert into public.ppg_lesson_step_options
  (lesson_key, step_order_index, option_key, option_th, option_en)
values
  ('chapter-01-lesson-01', 4, 'a', 'แสดงข้อมูลทุกอย่างที่รู้', 'To show every detail you know'),
  ('chapter-01-lesson-01', 4, 'b', 'สร้างความบันเทิงเท่านั้น', 'To entertain only'),
  ('chapter-01-lesson-01', 4, 'c', 'สือสารความคิดหนึงเรื่องหใ้ผู้ฟังเข้าใจและนำไปใช้', 'To communicate one idea the audience can understand and act on'),
  ('chapter-01-lesson-02', 4, 'a', 'ข้อความยาว', 'A long paragraph'),
  ('chapter-01-lesson-02', 4, 'b', 'แผนภูมิแท่ง', 'A bar chart'),
  ('chapter-01-lesson-02', 4, 'c', 'ไอคอนใหญ่', 'A large icon'),
  ('chapter-01-lesson-03', 4, 'a', 'หนึงสไลด์หนึงความคิด แบบอักษรอ่านง่าย และสไตล์เดียวกันทั้งชุด', 'One idea per slide, readable type, and one style across the deck'),
  ('chapter-01-lesson-03', 4, 'b', 'ใส่ทุกความคิดในสไลด์เดียวเพื่อประหยัดเวลา', 'Put every idea on one slide to save time'),
  ('chapter-01-lesson-03', 4, 'c', 'เปลี่ยนสีและแบบอักษรทุกสไลด์เพื่อความน่าสนใจ', 'Change colours and fonts on every slide for interest'),
